import base64
import json
import os
import re
from typing import Dict, List


class PackageNotFoundError(Exception):
    pass


class DependencyConflictError(Exception):
    pass


class CircularDependencyError(Exception):
    pass


def _parse_version(v: str):
    """Parse a version string into a comparable tuple.

    Numeric components become ints, non-numeric remain strings.
    """
    v = str(v).strip()
    # split on '.' '-' '+' '_'
    parts = re.split(r"[.\-+_]", v)
    out = []
    for p in parts:
        p = p.strip()
        if p == "":
            continue
        if p.isdigit():
            out.append(int(p))
        else:
            # try leading numeric prefix, e.g. '2rc1' -> (2, 'rc1')
            m = re.match(r"^(\d+)(.*)$", p)
            if m and m.group(2):
                out.append(int(m.group(1)))
                out.append(m.group(2))
            else:
                # try pure int conversion fallback
                try:
                    out.append(int(p))
                except ValueError:
                    out.append(p)
    return tuple(out)


def _compare_versions(v1: str, v2: str) -> int:
    """Return -1 if v1 < v2, 0 if equal, 1 if v1 > v2."""
    t1 = _parse_version(v1)
    t2 = _parse_version(v2)
    n = max(len(t1), len(t2))
    for i in range(n):
        a = t1[i] if i < len(t1) else 0
        b = t2[i] if i < len(t2) else 0
        if type(a) != type(b):
            # numeric components compare numerically; int < str convention
            # convert both to string comparison as fallback, but keep
            # ints ordered before strings deterministically
            if isinstance(a, int) and isinstance(b, str):
                return -1
            if isinstance(a, str) and isinstance(b, int):
                return 1
        if a < b:
            return -1
        if a > b:
            return 1
    return 0


_OP_PATTERN = re.compile(r"^\s*(>=|<=|==|>|<|=)?\s*(.+?)\s*$")


def _satisfies_single(version: str, single: str) -> bool:
    single = single.strip()
    if single == "" or single == "*":
        return True
    m = _OP_PATTERN.match(single)
    if not m:
        raise ValueError(f"Invalid version specifier: {single!r}")
    op = m.group(1) or "=="
    target = m.group(2).strip()
    if target == "" or target == "*":
        return True
    if op == "=":
        op = "=="
    cmp = _compare_versions(version, target)
    if op == "==":
        return cmp == 0
    if op == ">=":
        return cmp >= 0
    if op == "<=":
        return cmp <= 0
    if op == ">":
        return cmp > 0
    if op == "<":
        return cmp < 0
    raise ValueError(f"Unsupported operator: {op!r}")


def satisfies(version: str, spec) -> bool:
    """Check whether `version` satisfies the constraint `spec`.

    `spec` may be None/empty (matches anything), a single constraint
    such as '>=1.0', or comma-separated conjunctions like '>=1.0, <3.0'.
    A bare version ('1.0.0') is treated as '==1.0.0'.
    """
    if spec is None:
        return True
    spec = str(spec).strip()
    if spec == "" or spec == "*":
        return True
    # conjunction split on comma
    parts = [p.strip() for p in spec.split(",")]
    # also allow space-separated conjunctions? Only split on whitespace
    # when it looks like multiple constraints to avoid breaking versions
    # with spaces (there are none). Handle e.g. ">1.0 <3.0".
    expanded = []
    for p in parts:
        # split on whitespace if more than one constraint glued by spaces
        # e.g. ">=1.0 <3.0" -> [">=1.0", "<3.0"]
        tokens = p.split()
        if len(tokens) > 1:
            # check if each token parses as a constraint; if the whole
            # part parses as one, keep it. Heuristic: if every token
            # starts with an operator or looks like a version, split.
            split_ok = True
            for t in tokens:
                if not _OP_PATTERN.match(t):
                    split_ok = False
                    break
            if split_ok:
                expanded.extend(tokens)
            else:
                expanded.append(p)
        else:
            expanded.append(p)
    return all(_satisfies_single(version, p) for p in expanded if p != "")


class DependencyResolver:
    """Loads a base64-encoded manifest registry and resolves build order."""

    def __init__(self, registry_path: str):
        self.registry_path = registry_path
        self.registry: Dict[str, Dict] = {}
        # aliases for test introspection compatibility
        self.packages = self.registry
        self.manifests = self.registry
        self._load_registry(registry_path)

    def _load_registry(self, registry_path: str):
        if not os.path.isdir(registry_path):
            raise FileNotFoundError(f"Registry path not found: {registry_path}")
        for fname in os.listdir(registry_path):
            if not fname.endswith(".manifest"):
                continue
            fpath = os.path.join(registry_path, fname)
            with open(fpath, "r", encoding="utf-8") as f:
                raw = f.read().strip()
            if not raw:
                continue
            # manifests are base64-encoded JSON
            try:
                decoded = base64.b64decode(raw, validate=False).decode("utf-8")
            except Exception:
                # fall back to raw JSON content for robustness
                decoded = raw
            try:
                data = json.loads(decoded)
            except json.JSONDecodeError:
                # maybe double-encoded or whitespace; try stripping
                data = json.loads(decoded.strip())
            name = data.get("name") or os.path.splitext(fname)[0]
            version = data.get("version", "0.0.0")
            deps = data.get("dependencies", {}) or {}
            self.registry[name] = {
                "name": name,
                "version": str(version),
                "dependencies": dict(deps),
            }

    def _load_root_dependencies(self, root_config_path: str) -> Dict[str, str]:
        with open(root_config_path, "r", encoding="utf-8") as f:
            config = json.load(f)
        if isinstance(config, dict):
            if "dependencies" in config and isinstance(config["dependencies"], dict):
                return {k: ("" if v is None else str(v)) for k, v in config["dependencies"].items()}
            # tolerate alternate key
            if "deps" in config and isinstance(config["deps"], dict):
                return {k: ("" if v is None else str(v)) for k, v in config["deps"].items()}
            # maybe {"name": ..., "version": ..., "dependencies": ...} handled above;
            # otherwise treat top-level mapping of name->spec as deps if values look like specs
            looks_like_dep_map = True
            for k, v in config.items():
                if not isinstance(k, str) or not isinstance(v, (str, type(None))):
                    looks_like_dep_map = False
                    break
            if looks_like_dep_map and len(config) > 0 and "name" not in config:
                return {k: ("" if v is None else str(v)) for k, v in config.items()}
            if len(config) == 0:
                return {}
            # config with name but no dependencies -> empty
            return {}
        if isinstance(config, list):
            # list of {"name":..., "version"/"constraint":...} ?
            deps: Dict[str, str] = {}
            for item in config:
                if isinstance(item, dict) and "name" in item:
                    spec = item.get("constraint", item.get("version", item.get("spec", "")))
                    deps[item["name"]] = "" if spec is None else str(spec)
            return deps
        return {}

    def resolve(self, root_config_path: str) -> List[Dict]:
        root_deps = self._load_root_dependencies(root_config_path)

        constraints: Dict[str, List[str]] = {k: [v] for k, v in root_deps.items()}

        visiting: List[str] = []
        visiting_set = set()
        visited = set()
        order: List[Dict] = []

        def check_constraints(pkg_name: str):
            if pkg_name not in self.registry:
                raise PackageNotFoundError(f"Package not found: {pkg_name}")
            ver = self.registry[pkg_name]["version"]
            for spec in constraints.get(pkg_name, []):
                if not satisfies(ver, spec):
                    raise DependencyConflictError(
                        f"Version conflict for {pkg_name}: version {ver} "
                        f"does not satisfy constraint {spec!r}"
                    )

        def dfs(pkg_name: str):
            if pkg_name not in self.registry:
                raise PackageNotFoundError(f"Package not found: {pkg_name}")
            # Always validate accumulated constraints, even for visited nodes
            check_constraints(pkg_name)
            if pkg_name in visited:
                return
            if pkg_name in visiting_set:
                cycle = visiting + [pkg_name]
                raise CircularDependencyError(
                    f"Circular dependency detected: {' -> '.join(cycle)}"
                )
            visiting.append(pkg_name)
            visiting_set.add(pkg_name)
            deps = self.registry[pkg_name].get("dependencies", {}) or {}
            for dep_name, dep_spec in deps.items():
                dep_spec = "" if dep_spec is None else str(dep_spec)
                constraints.setdefault(dep_name, []).append(dep_spec)
                dfs(dep_name)
            visiting_set.remove(pkg_name)
            visiting.pop()
            visited.add(pkg_name)
            order.append(
                {"name": pkg_name, "version": self.registry[pkg_name]["version"]}
            )

        for name in list(root_deps.keys()):
            dfs(name)

        return order
