    d = tempfile.mkdtemp()
    for name, manifest in pkgs.items():
        raw = json.dumps(manifest).encode("utf-8")
        enc = base64.b64encode(raw).decode("ascii")
        with open(os.path.join(d, name + ".manifest"), "w") as f:
